class MinStack:
    def __init__(self):
        self.items = []

    def push(self, val: int) -> None:
        smallest = min(val, self.items[-1][1]) if self.items else val
        self.items.append((val, smallest))

    def pop(self) -> None:
        self.items.pop()

    def top(self) -> int:
        return self.items[-1][0]

    def getMin(self) -> int:
        return self.items[-1][1]
